__NUXT_JSONP__("/svet/stat/senegal/vyrobky", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{tabsLoad:{tabWhatToSee:d,tabPrice:d,tabPeople:d,tabTrip:d,tabContact:d,tabHotel:d,tabNeighboring:g,tabVideos:f,tabArticles:f,tabWallSockets:k,tabChains:1,tabFauna:f,tabFlora:f,tabFoods:f,tabBrands:f},place:[{tld:".sn",name:"Senegal",area:196722,population:16882430,slug:l,id_continent:g,information_chatgpt:"\u003Cp\u003ESenegal je země ležící na západním pobřeží Afriky. Má rozlohu přes 190 tisíc kilometrů čtverečních a je domovem pro více než 16 milionů lidí. Hlavním městem je Dakar, který je znám svým kulturním bohatstvím a moderní architekturou.\u003C\u002Fp\u003E\n\u003Cp\u003ESenegal má bohatou historii a kulturu. Země je známá svou hudbou a tancem, zejména žánrem zvaným Mbalax. Mezi další kulturní dědictví patří tradiční řemesla, jako jsou tkaní košťat, zpracování kovů a dřeva, či zpracování kůže.\u003C\u002Fp\u003E\n\u003Cp\u003ESenegal má také nádherné pláže, které jsou oblíbenou turistickou destinací. Nejznámější z nich je pláž Saly, která je ideálním místem pro odpočinek a relaxaci. Mezi další zajímavé místa patří národní park Niokolo-Koba, který se rozprostírá na území přes 9 tisíc kilometrů čtverečních a je domovem pro mnoho druhů zvířat, jako jsou lvi, sloni, hroši a krokodýli.\u003C\u002Fp\u003E\n\u003Cp\u003EKuchyně Senegalu je plná exotických a chutných pokrmů. Mezi nejznámější patří rybí pokrmy, jako je Thieboudienne (rybí pokrm s rýží), nebo Yassa (grilované kuřecí maso s cibulí a citronem). Dále stojí za ochutnání také různé druhy omáček a koření, které jsou charakteristické pro senegalskou kuchyni.\u003C\u002Fp\u003E\n\u003Cp\u003ESenegal je také domovem pro mnoho trhů a obchodů, kde můžete najít místní řemesla a zboží, jako jsou tradiční šperky, tkané koše, či různé druhy koření a bylin. Mezi nejoblíbenější nákupní místa patří trh v Dakaru, nebo trhy v městech Saint-Louis a Louga.\u003C\u002Fp\u003E",money_prices:[{name:"Taxi (cena za km)",value:m,date_update:b},{name:"Hlavní jídlo",value:5000,date_update:b},{name:"Chleba",value:m,date_update:b},{name:"Mléko",value:700,date_update:b},{name:"Voda (500ml)",value:200,date_update:b},{name:"Espresso",value:i,date_update:b},{name:"Zmrzlina (jeden kopeček)",value:300,date_update:b},{name:"Pivo",value:i,date_update:b},{name:"Krabička cigaret",value:i,date_update:b},{name:"Bic Mac",value:a,date_update:b},{name:"Coca Cola (500ml)",value:500,date_update:b}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"33",date_update:h},{name:"Policie",value:"17",date_update:h},{name:"Hasiči",value:"18",date_update:h},{name:"Zdravotnická záchranná služba",value:"15",date_update:h},{name:"Turistická policie",value:"800 00 20 20",date_update:h}],phone_prefix:"+221",coordinates:[{latitude:"14.4974",longitude:"-14.4524"}],people_religion:[{name:"Islám",value:"95%",date_update:c},{name:"Křesťanství",value:n,date_update:c},{name:"Tradiční africká náboženství",value:"1%",date_update:c},{name:"Nevěřící",value:"0.2%",date_update:c},{name:"Jiná náboženství",value:"0.8%",date_update:c}],people_nationality:[{name:"Wolofové",value:"38%",date_update:c},{name:"Pularové",value:"26%",date_update:c},{name:"Sererové",value:"15%",date_update:c},{name:"Diolové",value:n,date_update:c},{name:"Mandingové",value:"3%",date_update:c},{name:"Jiné",value:"14%",date_update:c}],visitors_entry:[{name:"Občanský průkaz",value:o,date_update:e},{name:"Cestovní pas",value:o,date_update:e},{name:"Vízum",value:"Pro občany České republiky není pro krátkodobý pobyt (do 90 dnů) v Senegalu nutné vízum. Pokud však cestujete za účelem studia, práce nebo trvalého pobytu, je nutné si vízum zajistit před cestou. Informace o vízových požadavcích pro cestující z jiných zemí najdete na webu senegalského ministerstva zahraničních věcí a senegalských velvyslanectvích.",date_update:e},{name:"Očkování",value:"Pro vstup do Senegalu není vyžadováno očkování. Nicméně je doporučeno očkování proti hepatitidě A a B, břišnímu tyfu a žluté zimnici. Pokud cestujete z oblasti s vysokým výskytem žluté zimnice, bude požadováno potvrzení o očkování.",date_update:e},{name:"Cestovní pojištění",value:"Pro vstup do Senegalu není vyžadováno cestovní nebo zdravotní pojištění, ale doporučuje se jej mít, aby se zajistilo krytí nákladů na lékařskou péči nebo repatriaci v případě potřeby.",date_update:e},{name:"Bezpečnostní situace",value:"Senegal je relativně stabilní země, ale stále existuje určitá míra kriminality, zejména v Dakaru a jeho předměstích. Cizinci by měli být opatrní a dodržovat základní bezpečnostní opatření, jako je udržování vysokého stupně obezřetnosti v hromadných dopravních prostředcích a na veřejných místech, nosení cenností v bezpečných místech a vyhnout se cestování sami v noci.",date_update:e},{name:"Další informace",value:"V Senegalu jsou časté výpadky elektřiny, takže je dobré mít na paměti, že hotely a jiná ubytování nemusí mít stabilní zdroj energie. V mnoha oblastech Senegalu je rozšířené pouliční obchodování a vyjednávání o ceně je zde běžné, takže pokud nakupujete na trzích nebo v obchodech mimo turistické zóny, je dobré se dohadovat o ceně zboží. Místní lidé jsou obecně přátelští a vstřícní k cizincům.",date_update:e}],type_place:p,id_image_cover:j,id_image_hero:j,id_city_main:2023,affiliate:[{name:"booking",value:d}],mpz:"SN",alerts:a,zoom:[{google:6,booking:7}],ids_neighboring_countries:[{id:85},{id:86},{id:93},{id:145},{id:151}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:205,facts_place:a,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2024-02-10T00:28:20.01422+00:00",name_original:a,currency:[{code:"XOF",name:"CFA frank"}]}],imagePlace:[{id:j,name:l,source:"\u002Fworld\u002Fstates\u002F",type:p,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:g,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:g,id_image_hero:g,zoom:[{google:2,booking:k}],information_author:a,seo_tags:a,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:a}]}],fetch:{},mutations:[]}}(null,"04-2021","04-2023",true,"05-2023",0,5,"09-2021",1000,354,3,"senegal",250,"4%","Pro vstup do Senegalu je potřeba mít platný cestovní pas. Občanský průkaz není dostatečným dokladem totožnosti pro vstup do země.","state")));